const reward=foe.boss?125:12+Math.floor(Math.random()*9)+(state.skills.scout||0)*4;
state.foe=null;
state.kills++;
state.progress[state.region]++;
state.renown+=foe.boss?45:4;
state.gold+=reward;
state.hp=Math.min(state.maxHp,state.hp+(foe.boss?25:5));
$('#enemybar').classList.remove('show');
$('#zoneTag').textContent='SAFE TRAIL';
addLog(`Defeated ${foe.name}. <b>+${reward} crowns</b>, +${foe.boss?45:4} renown.`);
