function openMerchant(){const stock=[{id:'potion',name:'Healing draught',desc:'Restore up to 45 vitality',cost:35,level:1},{id:'steel',name:'Steel longsword',desc:'+5 power · level 4',cost:190,level:4},{id:'frost',name:'Frostguard mail',desc:'+4 guard · level 6',cost:260,level:6},{id:'dragon',name:'Drakebone greatblade',desc:'+8 power · level 9',cost:520,level:9},{id:'might',name:'Tome of Might',desc:'Permanently learn +3 power · level 3',cost:145,level:3},{id:'ward',name:'Tome of Warding',desc:'Permanently learn +3 guard · level 3',cost:145,level:3},{id:'pony',name:'Trail Pony',desc:'A faithful mount · faster travel',cost:120,level:1},{id:'stag',name:'Frost Stag',desc:'Swift mount · level 5',cost:280,level:5}];
const loot=state.inventory.map((it,n)=>`<div class="property"><div><b>${it.rarity} ${it.name}</b><div class="sub">Loot · ${it.value||20} crowns</div></div><button class="smallbtn" onclick="sellItem(${n})">SELL</button></div>`).join('');
