window.sellItem=index=>{sellItem(index);
openMerchant()};

window.purchase=id=>{const stock={potion:{cost:35},steel:{cost:190,level:4,item:{name:'Steel longsword',rarity:'Rare',type:'weapon',power:5,value:95}},frost:{cost:260,level:6,item:{name:'Frostguard mail',rarity:'Rare',type:'armor',defense:4,value:130}},dragon:{cost:520,level:9,item:{name:'Drakebone greatblade',rarity:'Epic',type:'weapon',power:8,value:260}},might:{cost:145,level:3},ward:{cost:145,level:3},pony:{cost:120,level:1},stag:{cost:280,level:5}},i=stock[id];
