--- function openQuests ---

function openQuests(){const data=[['trail','Roadside Relief','Defeat 3 enemies',45,8],['guardian','Guardian Bounty','Defeat a regional guardian',100,15],['champion','Realm Champion','Defeat all 3 regional guardians',220,25]],html=data.map(([id,name,goal,gold,renown])=>{const q=state.quests[id],target=id==='trail'?3:id==='guardian'?1:3;
return `<div class="property"><div><b>${name}</b><div class="sub">${q.claimed?'Reward claimed':q.done?`Complete · reward ${gold} crowns, ${renown} renown`:`${goal} · ${Math.min(q.progress,target)} / ${target}`}</div></div><button class="smallbtn" onclick="claimQuest('${id}')" ${!q.done||q.claimed?'disabled':''}>${q.claimed?'DONE':q.done?'CLAIM':'TRACKED'}</button></div>`}).join('');
openModal(`<button class="close" onclick="closeModal()">✕</button><h2>ROYAL QUESTS</h2><p>Prove your worth across the frontier. Every reward must be claimed before the throne will recognize you.</p>${html}`)}
window.claimQuest=id=>{const rewards={trail:{gold:45,renown:8},guardian:{gold:100,renown:15},champion:{gold:220,renown:25,potions:2}},q=state.quests[id],r=rewards[id];
if(!q||!q.done||q.claimed)return;
q.claimed=true;
state.gold+=r.gold;
state.renown+=r.renown;
state.potions+=r.potions||0;
addLog(`Claimed ${id} quest reward: +${r.gold} crowns, +${r.renown} renown.`);
toast('Quest reward claimed.');
openQuests();
render()};


--- function showMap ---

function showMap(){openModal(`<button class="close" onclick="closeModal()">✕</button><h2>THE REALMS OF IRONVALE</h2><p>Defeat two foes to draw out a guardian. Guardians and level requirements open the road ahead.</p><div class="choices">${Object.entries(regions).map(([id,r])=>{const req=regionRequirement(id);
const status=req?`LOCKED · ${req.replace(/\.$/,'')}`:id==='woods'?'OPEN TRAIL':id==='capital'?'ROYAL DISTRICT · Throne requires 250 renown, Stone Keep & all quests':`Guardian ${state.bossKills[id]?'defeated':'unfound'} · ${state.progress[id]} foes`;
return `<button class="choice" onclick="travel('${id}')"><strong>${r.icon} ${r.name} · ${r.range}</strong><span>${status}</span></button>`}).join('')}</div>`)}

window.travel=id=>{closeModal();
unlockRegion(id)};

window.closeModal=()=>$('#modalBg').classList.remove('open');


